import { selectScopedPairs, type ActionType, type CaseRecord, type DecisionRecord, type PairFact, type Uom } from '../data';
import { useViewState, useWorkspace } from '../context/WorkspaceContext';
import { observationMatchesPair } from '../context/observationScope';
import { Button, DesignCheckbox, DesignInput, DesignTextarea, NativeDesignSelect, DataState, EvidenceMenu, Pill, WorkspaceCard } from '../components/ui';
import { DetailHeading, Metric, ScopeNote } from './viewHelpers';
import { exportRows } from '../helpers/exportWorkbook';
import { validDate } from './decisionRules';
import styles from './decisions.module.css';

const ASSORTMENT_ACTIONS: ActionType[] = ['Keep', 'Add', 'Drop', 'Swap'];
const SUPPLY_ACTIONS: ActionType[] = ['Chase existing inbound', 'Transfer', 'Bulk out', 'Stop buy'];
const dateAfter = (date: string, days: number) => { const value = new Date(date + 'T00:00:00Z'); value.setUTCDate(value.getUTCDate() + days); return Number.isFinite(value.valueOf()) ? value.toISOString().slice(0, 10) : date; };
interface DraftForm { action: ActionType; pairIds: string[]; quantity: string; uom: Uom; reason: string; owner: string; effectiveDate: string; reviewDate: string; evidenceIds: string[]; outgoingItemId: string; incomingItemId: string; destinationStoreId: string; linkedDecisionId: string }

export function CaseDetailView() {
  const workspace = useWorkspace();
  const { scope, dataset, route, cases, navigate, drafts, explainView } = workspace;
  const record = cases.find(record => record.id === route.id);
  const scopedPairs = selectScopedPairs(scope, dataset);
  if (!record) return <DataState state="empty" title="Review case not found" description="Choose an existing case from the decision queue."><Button onClick={() => navigate({ view: 'decisions' })}>Open queue</Button></DataState>;
  const pair = scopedPairs.find(pair => pair.itemId === record.itemId && pair.storeId === record.storeId);
  if (!pair) return <DataState state="empty" title="Case is outside the applied assortment scope" description="The case remains recorded. Return to the queue or adjust the workspace filters to inspect its authorized evidence."><Button onClick={() => navigate({ view: 'decisions' })}>Return to queue</Button></DataState>;
  const decisions = drafts.filter(decision => decision.caseId === record.id);
  return <div className={styles.page}>
    <DetailHeading eyebrow={`Decision case · ${record.id}`} title={record.title} description={`${record.itemId} at ${pair.store.name} · ${record.queue}`} actions={<><Pill tone={record.priority === 'Critical' ? 'danger' : record.priority === 'High' ? 'warning' : 'neutral'}>{record.priority}</Pill><Pill>{record.state}</Pill><Button onClick={() => navigate({ view: 'pair', id: record.itemId, storeId: record.storeId })}>Open pair evidence</Button></>}/>
    <ScopeNote scope={scope} extra={<span>Exact case pair · {pair.id}</span>}/>
    <div className={styles.caseLayout}><div className={styles.evidenceStack}>
      <WorkspaceCard title="Why this case needs review" subtitle="The triggering signal is retained as recorded. Current pair facts remain separately dated." actions={<EvidenceMenu title="Case evidence" definition="Priority comes from a rule evaluation. A case is not an approved assortment or supply action. Its original actual, threshold and rule version remain unchanged when rules are republished." onExport={() => exportRows(`${record.id} case evidence`, [{ Case: record.id, Pair: pair.id, Rule: record.ruleId, 'Rule version': record.ruleVersion, 'Recorded metric': record.metric, 'Recorded actual': record.actual, Threshold: record.threshold, 'Recorded evaluation': record.evaluatedAt, 'Recorded scope': JSON.stringify(record.evaluationScope ?? {}), 'Current sales': pair.sales, 'Current comparison': pair.comparisonSales, 'Current sellable OH': pair.sellableOh, 'Current OH cost': pair.ohCost, Owner: record.owner, Evidence: record.evidenceIds.join(', ') }], scope, { dataset, contributingPairs: [pair] })} onExplain={() => explainView({ title: `${record.id} case evidence`, selection: { label: record.title, caseIds: [record.id], itemIds: [record.itemId], storeIds: [record.storeId] }, evidence: record.evidenceIds })}/> }>
        <dl className={styles.facts}><dt>Trigger metric</dt><dd>{record.metric}</dd><dt>Recorded actual</dt><dd><Metric metric={record.actual} unit/></dd><dt>Threshold</dt><dd>{record.threshold}</dd><dt>Rule version</dt><dd>{record.ruleId} · v{record.ruleVersion}</dd><dt>Owner / review due</dt><dd>{record.owner} · {record.reviewDate}</dd><dt>Evaluation dates</dt><dd>{String((record as unknown as { evaluatedAt?: string }).evaluatedAt ?? 'Not recorded on this case; current scope dates below do not replace them.')}</dd><dt>Recorded evaluation scope</dt><dd>{record.evaluationScope ? `${record.evaluationScope.window ?? 'Window not recorded'} · stock ${record.evaluationScope.stockAsOf ?? 'not recorded'} · range ${record.evaluationScope.rangeAsOf ?? 'not recorded'} · ${record.evaluationScope.dataVersion ?? 'Data version not recorded'}` : 'Not recorded; do not infer from the currently selected period.'}</dd><dt>Linked evidence</dt><dd>{record.evidenceIds.join(', ') || 'No source links recorded'}</dd></dl>
        {record.signals && record.signals.length > 0 && <details className={styles.details}><summary>All recorded signals · {record.signals.length}</summary><ol className={styles.history}>{record.signals.map((signal, index) => <li key={`${signal.ruleId}:${signal.ruleVersion}:${index}`}><strong>{signal.ruleId} v{signal.ruleVersion}</strong><p>{signal.metric} · <Metric metric={signal.actual} unit/> · {signal.threshold}</p><small>{signal.evidenceIds.join(', ')}</small></li>)}</ol></details>}
        <div className={styles.evidenceClass}><Pill>Observed / recorded signal</Pill><p>{record.observation || 'No observation text recorded.'}</p></div><div className={styles.evidenceClass}><Pill tone="warning">Hypothesis · requires validation</Pill><p>{record.hypothesis || 'No causal explanation has been established. Review availability, range history, demand and field evidence.'}</p></div>
      </WorkspaceCard>
      <WorkspaceCard title="Current pair facts" subtitle={`${scope.window} · stock ${scope.stockAsOf} · range ${scope.rangeAsOf} · ${dataset.version}`}>
        <dl className={styles.facts}><dt>Product</dt><dd><button className={styles.link} onClick={() => navigate({ view: 'item', id: pair.itemId })}>{pair.itemId} · {pair.item.name}</button></dd><dt>Store</dt><dd><button className={styles.link} onClick={() => navigate({ view: 'store', id: pair.storeId, subview: 'assortment', focusItemId: pair.itemId })}>{pair.storeId} · {pair.store.name}</button></dd><dt>Range / eligibility</dt><dd>{pair.range} · {pair.eligibility} · {pair.matrixState}</dd><dt>Net sales / comparison</dt><dd><Metric metric={pair.sales}/> / <Metric metric={pair.comparisonSales}/></dd><dt>Sales change</dt><dd><Metric metric={pair.salesChange}/> · absolute <Metric metric={pair.salesDelta}/></dd><dt>Sellable / physical OH</dt><dd><Metric metric={pair.sellableOh} unit/> / <Metric metric={pair.physicalOh} unit/></dd><dt>OH cost / coverage</dt><dd><Metric metric={pair.ohCost}/> / <Metric metric={pair.wos} unit/></dd><dt>Open inbound</dt><dd><Metric metric={pair.openInbound} unit/> · not sellable stock today</dd></dl>
        <details className={styles.details}><summary>Inspect existing supply and shared DC evidence</summary><ol className={styles.history}>{pair.supply.map(line => <li key={line.id}><strong>{line.id} · {line.kind}</strong><p>{line.quantity.toLocaleString()} {line.uom} · {line.kind === 'dc-pool' ? `${line.dcId} shared pool` : line.storeId ?? line.dcId ?? 'Location not assigned'} · {line.status}</p><small>{line.eta ? `ETA ${line.eta}` : line.date} · source {line.sourceRef}</small></li>)}</ol>{!pair.supply.length && <p className={styles.helper}>No connected supply line. Absence of a line is not evidence that no replenishment plan exists.</p>}</details>
        <div className={styles.actions}><Button onClick={() => navigate({ view: 'pair', id: pair.itemId, storeId: pair.storeId, subview: 'availability' })}>Availability and supply</Button><Button onClick={() => navigate({ view: 'pair', id: pair.itemId, storeId: pair.storeId, subview: 'history' })}>Range and PLR history</Button></div>
        <p className={styles.helper}>A sales delta does not establish lost sales or a cause. Review alternative explanations and concurrent interventions before deciding.</p>
      </WorkspaceCard>
      <CaseAdministration record={record} decisions={decisions}/><CaseNotes record={record}/>
    </div><div className={styles.evidenceStack}><DraftAction record={record} pair={pair} scopedPairs={scopedPairs}/><WorkspaceCard title="Decision records" subtitle="Assortment choices and supply responses can be linked; neither executes an operational change here.">{!decisions.length ? <DataState state="empty" description="No action draft has been saved for this case."/> : decisions.map(decision => <DecisionLifecycle key={decision.id} decision={decision} record={record}/>)}</WorkspaceCard></div></div>
  </div>;
}

function DraftAction({ record, pair, scopedPairs }: { record: CaseRecord; pair: PairFact; scopedPairs: PairFact[] }) {
  const { scope, dataset, can, saveDraft, drafts } = useWorkspace();
  const inbound = pair.supply.filter(line => line.kind === 'open-order' && !line.reviewId);
  const defaults: DraftForm = { action: inbound.length && record.queue === 'Shortages' ? 'Chase existing inbound' : 'Keep', pairIds: [pair.id], quantity: '', uom: pair.item.uom, reason: '', owner: record.owner === 'Unassigned' ? '' : record.owner, effectiveDate: scope.rangeAsOf, reviewDate: dateAfter(scope.rangeAsOf, 7), evidenceIds: [...new Set([pair.id, ...record.evidenceIds])], outgoingItemId: pair.itemId, incomingItemId: '', destinationStoreId: '', linkedDecisionId: '' };
  const [form, setForm] = useViewState<DraftForm>(`case-action-draft-${record.id}`, defaults);
  const [errors, setErrors] = useViewState<string[]>(`case-action-errors-${record.id}`, []);
  const [editingId, setEditingId] = useViewState(`case-editing-decision-${record.id}`, '');
  const patch = (value: Partial<DraftForm>) => setForm(previous => ({ ...previous, ...value }));
  const availablePairs = scopedPairs.filter(candidate => candidate.itemId === pair.itemId);
  const selected = availablePairs.filter(candidate => form.pairIds.includes(candidate.id));
  const selectedSupply = selected.flatMap(candidate => candidate.supply.filter(line => line.kind === 'open-order' && !line.reviewId));
  const sourceLines = [...new Map(selectedSupply.map(line => [line.id, line])).values()];
  const evidence = [...new Set([...selected.map(pair => pair.id), ...record.evidenceIds, ...sourceLines.map(line => line.id)])];
  const quantityRequired = ['Chase existing inbound', 'Transfer', 'Bulk out'].includes(form.action);
  const save = () => {
    const issues: string[] = [];
    if (!form.pairIds.length || selected.length !== form.pairIds.length) issues.push('Select exact pairs inside the current scope.');
    if (!form.owner.trim() || !form.reason.trim()) issues.push('An owner and decision reason are required.');
    if (!validDate(form.effectiveDate) || !validDate(form.reviewDate) || form.reviewDate < form.effectiveDate) issues.push('Use valid effective and review dates; review must be on or after the effective date.');
    if (!form.evidenceIds.length) issues.push('Link at least one measured or authored evidence record.');
    if (quantityRequired && (!(Number(form.quantity) > 0) || !Number.isFinite(Number(form.quantity)))) issues.push('A supply response needs a positive compatible quantity.');
    if (form.action === 'Swap' && (!dataset.products.some(item => item.id === form.incomingItemId) || form.incomingItemId === form.outgoingItemId)) issues.push('Choose different existing outgoing and incoming SKUs.');
    if (form.action === 'Transfer' && (!form.destinationStoreId || selected.some(pair => pair.storeId === form.destinationStoreId))) issues.push('Choose a destination store different from every selected source store.');
    if (['Transfer', 'Bulk out'].includes(form.action) && (selected.some(pair => pair.sellableOh.value === null || (pair.sellableOh.value ?? 0) < 0) || Number(form.quantity) > selected.reduce((sum, pair) => sum + (pair.sellableOh.value ?? 0), 0))) issues.push('Quantity exceeds verified sellable source stock, or source inventory needs reconciliation.');
    if (issues.length) { setErrors(issues); return; }
    const result = saveDraft({ ...(editingId ? { id: editingId } : {}), caseId: record.id, action: form.action, pairIds: form.pairIds, ...(quantityRequired ? { quantity: Number(form.quantity), uom: form.uom } : {}), owner: form.owner.trim(), reason: form.reason.trim(), effectiveDate: form.effectiveDate, reviewDate: form.reviewDate, evidenceIds: form.evidenceIds, ...(form.action === 'Swap' ? { outgoingItemId: form.outgoingItemId, incomingItemId: form.incomingItemId } : {}), ...(form.action === 'Transfer' ? { destinationStoreId: form.destinationStoreId } : {}), linkedDecisionId: form.linkedDecisionId || undefined, beforeScope: form.pairIds, afterScope: form.action === 'Swap' ? form.pairIds.map(id => `${form.incomingItemId}:${id.split(':').slice(1).join(':')}`) : form.pairIds });
    if (result) { setErrors([]); setEditingId(''); setForm({ ...defaults, action: form.action }); }
    else setErrors(['Draft was not saved. Resolve the validation message above; the entered values are retained.']);
  };
  return <WorkspaceCard title={editingId ? `Edit draft ${editingId}` : 'Draft a scoped response'} subtitle="Save creates a draft only. Submit, approval and execution acknowledgement are explicit later steps.">
    <div className={styles.draftForm}>
      <NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Action" value={form.action} disabled={!can('draft')} onChange={event => patch({ action: event.target.value as ActionType, quantity: '' })}><optgroup label="Assortment choice">{ASSORTMENT_ACTIONS.map(action => <option value={action} key={action}>{action}</option>)}</optgroup><optgroup label="Supply / disposition response">{SUPPLY_ACTIONS.map(action => <option value={action} key={action}>{action}</option>)}</optgroup></NativeDesignSelect>
      <details className={styles.details} open><summary>Exact SKU–store scope · {form.pairIds.length} pairs</summary><div className={styles.checkList}>{availablePairs.map(candidate => <DesignCheckbox key={candidate.id} label={<><span>{candidate.itemId} × {candidate.storeId} · {candidate.store.name}<small className={styles.secondary}>{candidate.range} · {candidate.matrixState} · sellable <Metric metric={candidate.sellableOh} unit/></small></span></>} disabled={!can('draft')} checked={form.pairIds.includes(candidate.id)} onChange={event => patch({ pairIds: event.target.checked ? [...form.pairIds, candidate.id] : form.pairIds.filter(id => id !== candidate.id) })}/>)}</div></details>
      {form.action === 'Swap' && <div className={styles.formGrid}><DesignInput className={styles.field} label="Outgoing SKU" readOnly value={form.outgoingItemId}/><NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Incoming SKU" value={form.incomingItemId} onChange={event => patch({ incomingItemId: event.target.value })}><option value="">Choose incoming SKU</option>{dataset.products.filter(item => item.id !== form.outgoingItemId).map(item => <option value={item.id} key={item.id}>{item.id} · {item.name}</option>)}</NativeDesignSelect><p className={`${styles.helper} ${styles.spanAll}`}>The outgoing/incoming IDs, selected stores and effective date form one reviewed change. Any supply response is a separate linked draft.</p></div>}
      {quantityRequired && <div className={styles.formGrid}><DesignInput className={styles.field} label="Quantity" type="number" min="0" step="any" value={form.quantity} onChange={event => patch({ quantity: event.target.value })}/><NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Compatible unit" value={form.uom} onChange={event => patch({ uom: event.target.value as Uom })}>{[...new Set(selected.map(pair => pair.item.uom).concat(form.uom))].map(unit => <option key={unit}>{unit}</option>)}</NativeDesignSelect></div>}
      {form.action === 'Transfer' && <NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Destination store" value={form.destinationStoreId} onChange={event => patch({ destinationStoreId: event.target.value })}><option value="">Choose destination</option>{dataset.stores.filter(store => !selected.some(pair => pair.storeId === store.id)).map(store => <option value={store.id} key={store.id}>{store.id} · {store.name}</option>)}</NativeDesignSelect>}
      {form.action === 'Chase existing inbound' && <div className={styles.notice}>Existing selected inbound: {sourceLines.reduce((sum, line) => sum + line.quantity, 0).toLocaleString()} {pair.item.uom}. Link an existing order below. Chasing requests follow-up on it and does not create another order.</div>}
      <DesignTextarea className={styles.field} label="Reason / alternatives considered" value={form.reason} onChange={event => patch({ reason: event.target.value })} placeholder="Explain the response, evidence, alternatives and any uncertain assumptions."/>
      <div className={styles.formGrid}><DesignInput className={styles.field} label="Owner" value={form.owner} onChange={event => patch({ owner: event.target.value })}/><NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Link another decision · optional" value={form.linkedDecisionId} onChange={event => patch({ linkedDecisionId: event.target.value })}><option value="">No linked decision</option>{drafts.filter(draft => draft.caseId === record.id && draft.id !== editingId).map(draft => <option key={draft.id} value={draft.id}>{draft.id} · {draft.action}</option>)}</NativeDesignSelect><DesignInput className={styles.field} label="Effective date" type="date" value={form.effectiveDate} onChange={event => patch({ effectiveDate: event.target.value })}/><DesignInput className={styles.field} label="Review date" type="date" value={form.reviewDate} onChange={event => patch({ reviewDate: event.target.value })}/></div>
      <details className={styles.details} open><summary>Linked evidence · {form.evidenceIds.length}</summary><div className={styles.checkList}>{evidence.map(id => <DesignCheckbox key={id} label={<>{id}</>} checked={form.evidenceIds.includes(id)} onChange={event => patch({ evidenceIds: event.target.checked ? [...new Set([...form.evidenceIds, id])] : form.evidenceIds.filter(value => value !== id) })}/>)}</div></details>
      <details className={styles.details}><summary>Load a saved draft for editing</summary><div className={styles.actions}>{drafts.filter(draft => draft.caseId === record.id && draft.state === 'Draft').map(draft => <Button key={draft.id} onClick={() => { setEditingId(draft.id); setErrors([]); setForm({ action: draft.action, pairIds: draft.pairIds, quantity: draft.quantity === undefined ? '' : String(draft.quantity), uom: draft.uom ?? pair.item.uom, reason: draft.reason, owner: draft.owner, effectiveDate: draft.effectiveDate, reviewDate: draft.reviewDate, evidenceIds: draft.evidenceIds, outgoingItemId: draft.outgoingItemId ?? pair.itemId, incomingItemId: draft.incomingItemId ?? '', destinationStoreId: String((draft as unknown as { destinationStoreId?: string }).destinationStoreId ?? ''), linkedDecisionId: String((draft as unknown as { linkedDecisionId?: string }).linkedDecisionId ?? '') }); }}>{draft.id} · {draft.action}</Button>)}</div></details>
      {errors.length > 0 && <div className={styles.errors} role="alert">{errors.map(error => <p key={error}>{error}</p>)}</div>}
      <div className={styles.formFooter}><Button variant="ghost" onClick={() => { setForm(defaults); setEditingId(''); setErrors([]); }}>Reset form</Button><Button variant="primary" disabled={!can('draft') || record.state === 'Resolved'} onClick={save}>{editingId ? 'Save draft changes' : 'Save draft'}</Button></div>
      <p className={styles.helper}>Source, supplier capacity and packaging approvals are not connected. No external commitment is executed. {can('draft') ? '' : 'Your current role can inspect evidence but cannot draft.'}</p>
    </div>
  </WorkspaceCard>;
}

function DecisionLifecycle({ decision, record }: { decision: DecisionRecord; record: CaseRecord }) {
  const { transitionDecision, can, scope, saveLearning, role, dataset } = useWorkspace();
  const [ack, setAck] = useViewState(`decision-ack-${decision.id}`, { reference: '', note: '', completed: decision.completedPairIds, failed: decision.failedPairIds, local: false });
  const [outcome, setOutcome] = useViewState(`decision-outcome-${decision.id}`, { start: decision.effectiveDate, end: decision.reviewDate, observation: '', interventions: '', conclusion: '', limitations: '', learning: false, confidence: 'Medium', nextReviewId: '', learningState: 'Pending' as 'Pending' | 'Accepted' });
  const [error, setError] = useViewState(`decision-lifecycle-error-${decision.id}`, '');
  const approved = ['Approved', 'Awaiting execution', 'Partially executed'].includes(decision.state);
  const learningConnected = dataset.versions.some(version => version.reviewId === scope.reviewId && version.id === scope.version);
  const acknowledge = () => {
    if (!ack.local || !ack.reference.trim() || (!ack.completed.length && !ack.failed.length)) { setError('Confirm this is a local simulation, enter an acknowledgement reference and mark completed or failed pairs.'); return; }
    const result = transitionDecision(decision.id, { type: 'execution-ack', executionRef: ack.reference.startsWith('SIM-') ? ack.reference : `SIM-${ack.reference}`, completedPairIds: ack.completed, failedPairIds: ack.failed, note: `Local simulation only. ${ack.note || 'No external execution system was called.'}` });
    if (result) setError(''); else setError('Acknowledgement was not saved. Resolve the validation message above.');
  };
  const review = () => {
    if (!validDate(outcome.start) || !validDate(outcome.end) || outcome.end < outcome.start || !outcome.observation.trim() || !outcome.conclusion.trim() || !outcome.limitations.trim()) { setError('Provide a valid observation window, observed result, conclusion and limitations.'); return; }
    if (outcome.learning && (!learningConnected || !outcome.nextReviewId.trim() || !can('author-learning') || outcome.learningState === 'Accepted' && !can('accept-learning'))) { setError('A connected original PLR/version and a destination next PLR are required before linking an accepted learning.'); return; }
    const note = `Outcome window ${outcome.start} to ${outcome.end}. Observed: ${outcome.observation}. Concurrent interventions: ${outcome.interventions || 'None recorded; absence is not evidence of none'}. Conclusion: ${outcome.conclusion}. Limitations: ${outcome.limitations}. Local execution simulation only; no causal uplift is asserted.`;
    const result = transitionDecision(decision.id, { type: 'review', note });
    if (!result) { setError('Review was not saved. Resolve the validation message above.'); return; }
    if (outcome.learning) saveLearning({ reviewId: scope.reviewId, version: scope.version, question: `What should the next PLR learn from ${decision.id}?`, evidenceIds: [...decision.evidenceIds, decision.id, decision.executionRef ?? ''], hypothesis: record.hypothesis || 'Review the observed outcome alongside other interventions.', conclusion: `${outcome.conclusion} Limitations: ${outcome.limitations}`, owner: decision.owner, confidence: outcome.confidence, pairIds: decision.pairIds, nextReviewId: outcome.nextReviewId.trim(), state: outcome.learningState });
    setError('');
  };
  return <article className={styles.recordCard} id={`decision-${decision.id}`}>
    <div className={styles.recordTop}><h3>{decision.id} · {decision.action}</h3><Pill tone={decision.state === 'Reviewed' ? 'success' : decision.state === 'Partially executed' ? 'warning' : 'neutral'}>{decision.state}</Pill></div>
    <dl className={styles.facts}><dt>Exact pairs</dt><dd>{decision.pairIds.join(', ')}</dd>{decision.action === 'Swap' && <><dt>Before → after</dt><dd>{decision.outgoingItemId} → {decision.incomingItemId} across the same selected stores</dd></>}<dt>Owner / reason</dt><dd>{decision.owner} · {decision.reason}</dd><dt>Effective / review</dt><dd>{decision.effectiveDate} / {decision.reviewDate}</dd><dt>Quantity</dt><dd>{decision.quantity === undefined ? 'Not applicable' : `${decision.quantity.toLocaleString()} ${decision.uom}`}</dd><dt>Execution reference</dt><dd>{decision.executionRef ?? 'None; approval does not establish execution'}</dd><dt>Acknowledged pairs</dt><dd>{decision.completedPairIds.length} completed · {decision.failedPairIds.length} failed · {decision.pairIds.length - new Set([...decision.completedPairIds, ...decision.failedPairIds]).size} pending</dd></dl>
    <div className={styles.actions}>
      {decision.state === 'Draft' && <Button disabled={!can('draft')} onClick={() => transitionDecision(decision.id, { type: 'submit', note: 'Submitted for approval; no execution requested.' })}>Submit for approval</Button>}
      {decision.state === 'Awaiting approval' && <Button variant="primary" disabled={!can('approve')} onClick={() => { const approved = transitionDecision(decision.id, { type: 'approve', note: `Approved by ${role} in the local design session.` }); if (approved) transitionDecision(decision.id, { type: 'await-execution', note: 'No execution acknowledgement exists. Awaiting explicit confirmation.' }); }}>Approve and await execution</Button>}
      {decision.state === 'Approved' && <Button disabled={!can('approve')} onClick={() => transitionDecision(decision.id, { type: 'await-execution', note: 'Approval retained; execution acknowledgement pending.' })}>Await execution</Button>}
      {!['Reviewed', 'Cancelled', 'Superseded'].includes(decision.state) && <><Button variant="ghost" disabled={!can(['Draft', 'Awaiting approval'].includes(decision.state) ? 'draft' : 'approve')} onClick={() => transitionDecision(decision.id, { type: 'cancel', note: 'Cancelled explicitly; prior evidence retained.' })}>Cancel decision</Button><Button variant="ghost" disabled={!can(['Draft', 'Awaiting approval'].includes(decision.state) ? 'draft' : 'approve')} onClick={() => transitionDecision(decision.id, { type: 'supersede', note: 'Superseded explicitly; retain this record and link any replacement draft.' })}>Supersede</Button></>}
    </div>
    {approved && <details className={styles.details}><summary>Record local execution acknowledgement</summary><p className={styles.helper}>Administrator capability is required. This records a labeled simulation and does not execute an order or update actual sales, stock or the original PLR.</p><div className={styles.formGrid}><DesignInput className={styles.field} label="Simulation acknowledgement reference" value={ack.reference} placeholder="SIM-reference" disabled={!can('record-execution')} onChange={event => setAck({ ...ack, reference: event.target.value })}/><DesignInput className={styles.field} label="Acknowledgement note" value={ack.note} disabled={!can('record-execution')} onChange={event => setAck({ ...ack, note: event.target.value })}/></div><table className={styles.ackTable}><thead><tr><th>Approved pair</th><th>Completed</th><th>Failed</th></tr></thead><tbody>{decision.pairIds.map(id => <tr key={id}><td>{id}</td><td><DesignCheckbox aria-label={`${id} completed`} disabled={!can('record-execution')} checked={ack.completed.includes(id)} onChange={event => setAck({ ...ack, completed: event.target.checked ? [...new Set([...ack.completed, id])] : ack.completed.filter(value => value !== id), failed: ack.failed.filter(value => value !== id) })}/></td><td><DesignCheckbox aria-label={`${id} failed`} disabled={!can('record-execution')} checked={ack.failed.includes(id)} onChange={event => setAck({ ...ack, failed: event.target.checked ? [...new Set([...ack.failed, id])] : ack.failed.filter(value => value !== id), completed: ack.completed.filter(value => value !== id) })}/></td></tr>)}</tbody></table><div className={styles.checkRow}><DesignCheckbox label={<>I am recording a local design-session simulation.</>} checked={ack.local} disabled={!can('record-execution')} onChange={event => setAck({ ...ack, local: event.target.checked })}/></div><Button disabled={!can('record-execution')} onClick={acknowledge}>Save local acknowledgement</Button></details>}
    {['Executed', 'Partially executed'].includes(decision.state) && <details className={styles.details}><summary>Review outcome and link a PLR learning</summary><div className={styles.outcomeForm}><div className={styles.formGrid}><DesignInput className={styles.field} label="Observation window start" type="date" value={outcome.start} onChange={event => setOutcome({ ...outcome, start: event.target.value })}/><DesignInput className={styles.field} label="Observation window end" type="date" value={outcome.end} onChange={event => setOutcome({ ...outcome, end: event.target.value })}/></div>{[['observation', 'Observed results and evidence'], ['interventions', 'Other concurrent interventions'], ['conclusion', 'Reviewed conclusion'], ['limitations', 'Limitations and alternative explanations']].map(([key, label]) => <DesignTextarea className={styles.field} key={key} label={`${label}`} value={outcome[key as 'observation']} onChange={event => setOutcome({ ...outcome, [key]: event.target.value })}/>)}<div className={styles.checkRow}><DesignCheckbox label={<>Link a learning to the next PLR</>} checked={outcome.learning} disabled={!learningConnected || !can('author-learning')} onChange={event => setOutcome({ ...outcome, learning: event.target.checked })}/></div>{outcome.learning && <div className={styles.formGrid}><NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Learning review state" value={outcome.learningState ?? 'Pending'} onChange={event => setOutcome({ ...outcome, learningState: event.target.value as 'Pending' | 'Accepted' })}><option>Pending</option><option disabled={!can('accept-learning')}>Accepted</option></NativeDesignSelect><DesignInput className={styles.field} label="Destination PLR ID" value={outcome.nextReviewId} onChange={event => setOutcome({ ...outcome, nextReviewId: event.target.value })}/><NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Confidence" value={outcome.confidence} onChange={event => setOutcome({ ...outcome, confidence: event.target.value })}>{['Low', 'Medium', 'High'].map(value => <option key={value}>{value}</option>)}</NativeDesignSelect></div>}<Button disabled={!can('draft')} onClick={review}>Save reviewed outcome</Button></div></details>}
    {error && <p className={styles.errors} role="alert">{error}</p>}
    <details className={styles.details}><summary>Audit trail · {decision.history.length} events</summary><ol className={styles.history}>{decision.history.map((event, index) => <li key={`${event.at}:${index}`}><strong>{event.state}</strong><p>{event.note}</p><small>{event.actor} · {event.at}</small></li>)}</ol></details>
  </article>;
}

function CaseAdministration({ record, decisions }: { record: CaseRecord; decisions: DecisionRecord[] }) {
  const { updateCase, can } = useWorkspace();
  const [owner, setOwner] = useViewState(`case-owner-${record.id}`, record.owner);
  const [date, setDate] = useViewState(`case-review-date-${record.id}`, record.reviewDate);
  const [error, setError] = useViewState(`case-administration-error-${record.id}`, '');
  const reviewed = decisions.some(decision => decision.state === 'Reviewed') && decisions.every(decision => ['Reviewed', 'Cancelled', 'Superseded'].includes(decision.state));
  return <WorkspaceCard title="Accountable follow-up" subtitle="Case ownership and review state are separate from approval and execution of a decision."><div className={styles.formGrid}><DesignInput className={styles.field} label="Case owner" value={owner} onChange={event => setOwner(event.target.value)} disabled={!can('draft')}/><DesignInput className={styles.field} label="Review due" type="date" value={date} onChange={event => setDate(event.target.value)} disabled={!can('draft')}/></div>{error && <p className={styles.errors} role="alert">{error}</p>}<div className={styles.actions} style={{ marginTop: 12 }}><Button disabled={!can('draft')} onClick={() => { if (!owner.trim() || !validDate(date)) { setError('Provide a case owner and a valid review date.'); return; } updateCase(record.id, { owner: owner.trim(), reviewDate: date }); setError(''); }}>Save owner and date</Button>{record.state === 'Open' && <Button disabled={!can('draft')} onClick={() => updateCase(record.id, { state: 'In review' })}>Start case review</Button>}{record.state !== 'Resolved' && <Button disabled={!can('draft') || !reviewed} onClick={() => updateCase(record.id, { state: 'Resolved' })}>Close reviewed case</Button>}</div>{!reviewed && <p className={styles.helper}>Closure becomes available after a recorded outcome review and after other linked decisions are reviewed, cancelled or superseded.</p>}</WorkspaceCard>;
}

function CaseNotes({ record }: { record: CaseRecord }) {
  const { observations, addObservation, can, scope } = useWorkspace();
  const [form, setForm] = useViewState(`case-note-${record.id}`, { text: '', author: '', observedOn: scope.stockAsOf, source: '', visibility: 'Review team', confidence: 'Medium', evidenceClass: 'merchant-observation', validationQuestion: '', alternatives: '', followUpOwner: '', dueDate: dateAfter(scope.stockAsOf, 7) });
  const [error, setError] = useViewState(`case-note-error-${record.id}`, '');
  const rows = observations.filter(note => observationMatchesPair(note, { id: `${record.itemId}:${record.storeId}`, itemId: record.itemId, storeId: record.storeId }));
  return <WorkspaceCard title="Evidence and field notes" subtitle="Authored observations and hypotheses retain provenance; neither is a measured cause.">
    {rows.map(note => <article className={styles.note} key={note.id}><Pill tone={note.evidenceClass === 'hypothesis' ? 'warning' : 'neutral'}>{note.evidenceClass.replaceAll('-', ' ')}</Pill><p>{note.text}</p><small>{note.author} · observed {note.observedOn} · recorded {note.recordedOn} · {note.source}</small><small className={styles.secondary}>{String((note as unknown as { visibility?: string }).visibility ?? 'Visibility not recorded')} · confidence {String((note as unknown as { confidence?: string }).confidence ?? 'not recorded')}</small></article>)}
    {!rows.length && <p className={styles.helper}>No field observations are recorded for this exact pair.</p>}
    <details className={styles.details}><summary>Add scoped evidence</summary><div className={styles.formGrid}><DesignTextarea className={`${styles.field} ${styles.spanAll}`} label="Observation or hypothesis" value={form.text} onChange={event => setForm({ ...form, text: event.target.value })}/><NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Evidence class" value={form.evidenceClass} onChange={event => setForm({ ...form, evidenceClass: event.target.value })}><option value="merchant-observation">Merchant observation</option><option value="hypothesis">Hypothesis requiring validation</option></NativeDesignSelect><DesignInput className={styles.field} label="Author" value={form.author} onChange={event => setForm({ ...form, author: event.target.value })}/><DesignInput className={styles.field} label="Observed date" type="date" value={form.observedOn} onChange={event => setForm({ ...form, observedOn: event.target.value })}/><DesignInput className={styles.field} label="Source or evidence reference" value={form.source} placeholder="Field visit, report ID or local reference" onChange={event => setForm({ ...form, source: event.target.value })}/>{form.evidenceClass === 'hypothesis' && <><DesignInput className={styles.field} label="Validation question" value={form.validationQuestion} onChange={event => setForm({ ...form, validationQuestion: event.target.value })}/><DesignInput className={styles.field} label="Alternative explanations" value={form.alternatives} onChange={event => setForm({ ...form, alternatives: event.target.value })}/><DesignInput className={styles.field} label="Validation owner" value={form.followUpOwner} onChange={event => setForm({ ...form, followUpOwner: event.target.value })}/><DesignInput className={styles.field} label="Validation due" type="date" value={form.dueDate} onChange={event => setForm({ ...form, dueDate: event.target.value })}/></>}<NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Visibility" value={form.visibility} onChange={event => setForm({ ...form, visibility: event.target.value })}><option>Review team</option><option>Category team</option></NativeDesignSelect><NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Confidence" value={form.confidence} onChange={event => setForm({ ...form, confidence: event.target.value })}>{['Low', 'Medium', 'High'].map(value => <option key={value}>{value}</option>)}</NativeDesignSelect></div>{error && <p className={styles.errors} role="alert">{error}</p>}<Button disabled={!can('draft')} onClick={() => { if (form.evidenceClass === 'hypothesis' && (!form.validationQuestion.trim() || !form.alternatives.trim() || !form.followUpOwner.trim() || !validDate(form.dueDate))) { setError('A hypothesis needs a validation question, alternatives, an owner and a valid due date.'); return; } if (!form.text.trim() || !form.author.trim() || !form.source.trim() || !validDate(form.observedOn)) { setError('Provide text, author, a valid observed date and a source reference.'); return; } addObservation({ ...form, text: form.text.trim(), source: form.source.trim(), itemIds: [record.itemId], storeIds: [record.storeId], recordedOn: new Date().toISOString(), evidenceIds: record.evidenceIds, evidenceClass: form.evidenceClass as any } as any); setForm({ ...form, text: '' }); setError(''); }}>Save field evidence</Button><p className={styles.helper}>A local reference is not an uploaded client attachment. Visibility is a proposed local workflow setting; production entitlements require the client policy.</p></details>
  </WorkspaceCard>;
}

