import { ButtonGroup, ImpactTabs } from '@shared/components/vendor/impact-ui';
import { selectedWeekIds, selectScopedPairs, type CaseRecord, type DecisionRecord } from '../data';
import { useViewState, useWorkspace } from '../context/WorkspaceContext';
import { Button, DesignCheckbox, DesignInput, DesignSelect, DesignTextarea, NativeDesignSelect, DataState, EvidenceMenu, MetricCard, Pill, SectionHeading, Toolbar, WorkspaceCard, WorkspaceTable, type WorkspaceColumn } from '../components/ui';
import { exportRows } from '../helpers/exportWorkbook';
import { Metric, ScopeNote } from './viewHelpers';
import { QUEUES, RULE_METRICS, caseMatchesQueue, newReviewRule, previewReviewRule, publishReviewRule, rulePreviewSignature, sourceMipRule, type PublishedRule, type ReviewRule, type RulePreview } from './decisionRules';
import { acceptedLearningDestinations, learningCaseLinks, learningOriginScope, learningRegisterRows, type LearningRegisterSettings } from './learningRegister';
import styles from './decisions.module.css';

const SUBVIEWS = [{ value: 'queue', label: 'Queue' }, { value: 'log', label: 'Decision log' }, { value: 'rules', label: 'Rules' }, { value: 'learnings', label: 'PLR learnings' }];
const priorityOrder = { Critical: 0, High: 1, Watch: 2 };
const tone = (priority: string) => priority === 'Critical' ? 'danger' as const : priority === 'High' ? 'warning' as const : 'neutral' as const;

export function DecisionsView() {
  const { route, scope, navigate } = useWorkspace();
  const selected = SUBVIEWS.some(tab => tab.value === route.subview) ? route.subview! : 'queue';
  return <div className={styles.page}>
    <SectionHeading title="Decisions" description="Investigate an exception, agree a response and retain the approval and outcome evidence."/>
    <ScopeNote scope={scope}/>
    <ImpactTabs tabNames={SUBVIEWS} tabPanels={SUBVIEWS.map(() => null)} value={selected} isBlueBg={false} onChange={(_event, value) => navigate({ view: 'decisions', subview: String(value) })}/>
    {selected === 'queue' ? <DecisionQueue/> : selected === 'log' ? <DecisionLog/> : selected === 'rules' ? <RulesWorkspace/> : <LearningRegister/>}
  </div>;
}

function DecisionQueue() {
  const workspace = useWorkspace();
  const { scope, dataset, cases, navigate, localSelection, setLocalSelection, explainView } = workspace;
  const [filters, setFilters] = useViewState('decision-queue-filters', { queue: 'All', search: '', priority: 'All', state: 'Open cases', owner: 'All' });
  const [sort, setSort] = useViewState<{ key: string; direction: 'asc' | 'desc' }>('decision-queue-sort', { key: 'priority', direction: 'asc' });
  const effectiveScope = localSelection?.weekIds ? { ...scope, weekIds: selectedWeekIds(scope, dataset).filter(id => localSelection.weekIds!.includes(id)) } : scope;
  const pairs = selectScopedPairs(effectiveScope, dataset).filter(pair => (!localSelection?.itemIds || localSelection.itemIds.includes(pair.itemId)) && (!localSelection?.storeIds || localSelection.storeIds.includes(pair.storeId)) && (!localSelection?.pairIds || localSelection.pairIds.includes(pair.id))), pairMap = new Map(pairs.map(pair => [pair.id, pair]));
  const scoped = cases.filter(record => pairMap.has(`${record.itemId}:${record.storeId}`) && (!localSelection?.caseIds || localSelection.caseIds.includes(record.id)) && (!localSelection?.itemIds || localSelection.itemIds.includes(record.itemId)) && (!localSelection?.storeIds || localSelection.storeIds.includes(record.storeId)));
  const rows = scoped.filter(record => caseMatchesQueue(record, filters.queue, pairMap.get(`${record.itemId}:${record.storeId}`)) && (filters.state === 'All' || filters.state === 'Open cases' ? filters.state === 'All' || record.state !== 'Resolved' : record.state === filters.state) && (filters.priority === 'All' || record.priority === filters.priority) && (filters.owner === 'All' || record.owner === filters.owner) && `${record.id} ${record.title} ${record.itemId} ${record.storeId} ${record.owner} ${record.observation}`.toLowerCase().includes(filters.search.toLowerCase()));
  rows.sort((a, b) => { const read = (record: CaseRecord) => sort.key === 'priority' ? priorityOrder[record.priority] : sort.key === 'item' ? record.itemId : sort.key === 'store' ? record.storeId : sort.key === 'owner' ? record.owner : sort.key === 'state' ? record.state : sort.key === 'review' ? record.reviewDate : record.id; const av = read(a), bv = read(b), order = typeof av === 'number' && typeof bv === 'number' ? av - bv : String(av).localeCompare(String(bv), undefined, { numeric: true }); return (sort.direction === 'asc' ? order : -order) || a.id.localeCompare(b.id); });
  const open = rows.filter(record => record.state !== 'Resolved'), itemCount = new Set(open.map(record => record.itemId)).size, pairCount = new Set(open.map(record => `${record.itemId}:${record.storeId}`)).size;
  const exportQueue = () => exportRows('Decision queue', rows.map(record => ({ Case: record.id, Title: record.title, Priority: record.priority, Queue: record.queue, SKU: record.itemId, Store: record.storeId, State: record.state, Owner: record.owner, 'Review date': record.reviewDate, Metric: record.metric, 'Actual value': record.actual.value, 'Metric unit': record.actual.unit, 'Value state': record.actual.state, Threshold: record.threshold, Rule: record.ruleId, 'Rule version': record.ruleVersion, Evidence: record.evidenceIds.join(', '), Observation: record.observation, Hypothesis: record.hypothesis })), effectiveScope, { dataset, viewState: { filters, sort, localSelection } });
  const columns: WorkspaceColumn<CaseRecord>[] = [
    { key: 'case', label: 'Case / signals', render: record => <><button className={styles.link} onClick={() => navigate({ view: 'case', id: record.id })}>{record.id} · {record.title}</button><small className={styles.secondary}>{record.queue} · {record.ruleId} v{record.ruleVersion}</small></> },
    { key: 'priority', label: 'Priority', render: record => <Pill tone={tone(record.priority)}>{record.priority}</Pill> },
    { key: 'item', label: 'Product', render: record => <button className={styles.link} onClick={() => navigate({ view: 'item', id: record.itemId })}>{record.itemId}<small className={styles.secondary}>{dataset.products.find(item => item.id === record.itemId)?.name}</small></button> },
    { key: 'store', label: 'Store', render: record => <button className={styles.link} onClick={() => navigate({ view: 'store', id: record.storeId, subview: 'assortment', focusItemId: record.itemId })}>{record.storeId}<small className={styles.secondary}>{dataset.stores.find(store => store.id === record.storeId)?.name}</small></button> },
    { key: 'actual', label: 'Actual / threshold', sortable: false, render: record => <><Metric metric={record.actual} unit/><small className={styles.secondary}>{record.threshold}</small></> },
    { key: 'stock', label: 'OH cost', align: 'right', sortable: false, render: record => <Metric metric={pairMap.get(`${record.itemId}:${record.storeId}`)?.ohCost}/> },
    { key: 'state', label: 'Case state', value: record => record.state }, { key: 'owner', label: 'Owner', value: record => record.owner }, { key: 'review', label: 'Review due', value: record => record.reviewDate },
  ];
  return <>
    <div className={styles.counts} aria-label="Decision queue counts"><MetricCard label="Open cases" value={open.length} helper={(['Critical', 'High', 'Watch'] as const).map(priority => `${priority} ${open.filter(record => record.priority === priority).length}`).join(' · ')}/><MetricCard label="Impacted SKUs" value={itemCount} helper="Distinct canonical products"/><MetricCard label="Impacted pairs" value={pairCount} helper="Distinct SKU–store combinations"/><MetricCard label="Scanned pairs" value={pairs.length} helper="Applied scope before queue filters"/></div>
    <WorkspaceCard title="Review queue" subtitle="Priority is an explainable signal. It does not approve a Drop, supply action or range change." actions={<EvidenceMenu title="Decision queue" definition="Open cases are deduplicated case IDs. SKU and pair counts are distinct and must not be added across overlapping signals. Scanned pairs describe the applied population before queue filters." onExport={exportQueue} onExplain={() => explainView({ title: 'Decision queue', selection: { label: `${filters.queue} queue`, caseIds: rows.map(record => record.id) }, evidence: rows.flatMap(record => record.evidenceIds) })}/> }>
      {localSelection && <div className={styles.notice}><span>Local selection · {localSelection.label}</span><Button variant="ghost" onClick={() => setLocalSelection(null)}>Clear local selection</Button></div>}
      <Toolbar className={styles.queueToolbar} ariaLabel="Queue filters"><NativeDesignSelect orientation="top" width={180} className={styles.field} label="Queue" value={filters.queue} onChange={event => setFilters({ ...filters, queue: event.target.value })}><option>All</option>{QUEUES.map(queue => <option key={queue}>{queue}</option>)}</NativeDesignSelect><DesignInput className={styles.field} label="Search" type="search" placeholder="Case, SKU, store or owner" value={filters.search} onChange={event => setFilters({ ...filters, search: event.target.value })}/><NativeDesignSelect orientation="top" width={180} className={styles.field} label="Priority" value={filters.priority} onChange={event => setFilters({ ...filters, priority: event.target.value })}>{['All', 'Critical', 'High', 'Watch'].map(priority => <option key={priority}>{priority}</option>)}</NativeDesignSelect><NativeDesignSelect orientation="top" width={180} className={styles.field} label="State" value={filters.state} onChange={event => setFilters({ ...filters, state: event.target.value })}>{['Open cases', 'All', 'Open', 'In review', 'Resolved'].map(state => <option key={state}>{state}</option>)}</NativeDesignSelect><NativeDesignSelect orientation="top" width={180} className={styles.field} label="Owner" value={filters.owner} onChange={event => setFilters({ ...filters, owner: event.target.value })}><option>All</option>{[...new Set(scoped.map(record => record.owner))].sort().map(owner => <option key={owner}>{owner}</option>)}</NativeDesignSelect><Button variant="ghost" onClick={() => setFilters({ queue: 'All', search: '', priority: 'All', state: 'Open cases', owner: 'All' })}>Reset queue filters</Button></Toolbar>
      <WorkspaceTable rows={rows} columns={columns} rowKey={record => record.id} caption="Cases in the applied assortment scope" sort={sort} onSort={setSort}/>
      <p className={styles.helper}>{rows.length} cases displayed. A pair may have several source focus tags; review its existing case before proposing another action. Snapshot {scope.stockAsOf} · {scope.window} · source {dataset.version}.</p>
    </WorkspaceCard>
  </>;
}

function DecisionLog() {
  const { scope, dataset, drafts, navigate, localSelection } = useWorkspace();
  const [filters, setFilters] = useViewState('decision-log-filters', { search: '', state: 'All' });
  const effectiveScope = localSelection?.weekIds ? { ...scope, weekIds: selectedWeekIds(scope, dataset).filter(id => localSelection.weekIds!.includes(id)) } : scope;
  const ids = new Set(selectScopedPairs(effectiveScope, dataset).filter(pair => (!localSelection?.itemIds || localSelection.itemIds.includes(pair.itemId)) && (!localSelection?.storeIds || localSelection.storeIds.includes(pair.storeId)) && (!localSelection?.pairIds || localSelection.pairIds.includes(pair.id))).map(pair => pair.id));
  const rows = drafts.filter(record => record.pairIds.some(id => ids.has(id)) && (!localSelection?.caseIds || localSelection.caseIds.includes(record.caseId)) && (filters.state === 'All' || record.state === filters.state) && `${record.id} ${record.action} ${record.owner} ${record.caseId} ${record.pairIds.join(' ')}`.toLowerCase().includes(filters.search.toLowerCase())).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt) || a.id.localeCompare(b.id));
  const columns: WorkspaceColumn<DecisionRecord>[] = [
    { key: 'id', label: 'Decision', render: record => <button className={styles.link} onClick={() => navigate({ view: 'case', id: record.caseId, subview: record.id })}>{record.id} · {record.action}</button> }, { key: 'state', label: 'State', render: record => <Pill tone={record.state === 'Reviewed' ? 'success' : record.state === 'Partially executed' ? 'warning' : 'neutral'}>{record.state}</Pill> },
    { key: 'pairs', label: 'Exact scope', render: record => <>{record.pairIds.length} pairs<small className={styles.secondary}>{record.pairIds.join(', ')}</small>{record.action === 'Swap' && <small className={styles.secondary}>{record.outgoingItemId} → {record.incomingItemId}</small>}</> },
    { key: 'quantity', label: 'Quantity', render: record => record.quantity === undefined ? 'Not applicable' : `${record.quantity.toLocaleString()} ${record.uom}` }, { key: 'owner', label: 'Owner', value: record => record.owner }, { key: 'dates', label: 'Effective / review', render: record => <>{record.effectiveDate}<small className={styles.secondary}>Review {record.reviewDate}</small></> },
    { key: 'ack', label: 'Execution evidence', render: record => record.executionRef ? <>{record.executionRef}<small className={styles.secondary}>{record.completedPairIds.length} complete · {record.failedPairIds.length} failed · {record.pairIds.length - new Set([...record.completedPairIds, ...record.failedPairIds]).size} pending</small></> : 'No acknowledgement' },
  ];
  return <WorkspaceCard title="Decision log" subtitle="A saved draft, an approval and an execution acknowledgement are separate auditable events. Cancelled and superseded records remain visible." actions={<Button disabled={!rows.length} onClick={() => exportRows('Decision log', rows.map(record => ({ Decision: record.id, Case: record.caseId, Action: record.action, State: record.state, Pairs: record.pairIds.join(', '), Quantity: record.quantity, UOM: record.uom, Reason: record.reason, Owner: record.owner, Effective: record.effectiveDate, Review: record.reviewDate, Execution: record.executionRef, Completed: record.completedPairIds.join(', '), Failed: record.failedPairIds.join(', '), History: JSON.stringify(record.history) })), effectiveScope, { dataset, viewState: { filters, localSelection } })}>Export log</Button>}>
    <Toolbar className={styles.queueToolbar}><DesignInput label="Search" type="search" aria-label="Search decision log" placeholder="Search decision, SKU or owner" value={filters.search} onChange={event => setFilters({ ...filters, search: event.target.value })}/><NativeDesignSelect orientation="top" width={180} className={styles.field} label="Decision state" value={filters.state} onChange={event => setFilters({ ...filters, state: event.target.value })}>{['All', 'Draft', 'Awaiting approval', 'Approved', 'Awaiting execution', 'Partially executed', 'Executed', 'Reviewed', 'Cancelled', 'Superseded'].map(state => <option key={state}>{state}</option>)}</NativeDesignSelect></Toolbar>
    <WorkspaceTable rows={rows} columns={columns} rowKey={record => record.id} caption="Decision history" emptyMessage="No decisions match this scope. Open a review case and save a draft to begin."/>
    <p className={styles.helper}>Local design-session records. No order, assortment change or external execution is made by this prototype.</p>
  </WorkspaceCard>;
}

function RulesWorkspace() {
  const { scope, dataset, can, role, addNotice, navigate } = useWorkspace();
  const [rule, setRule] = useViewState<ReviewRule>('decision-rule-draft', newReviewRule(scope));
  const [preview, setPreview] = useViewState<RulePreview | null>('decision-rule-preview', null);
  const [versions, setVersions] = useViewState<PublishedRule[]>('decision-rule-versions', []);
  const [errors, setErrors] = useViewState<string[]>('decision-rule-errors', []);
  const patch = (value: Partial<ReviewRule>) => setRule(previous => ({ ...previous, ...value }));
  const current = preview?.signature === rulePreviewSignature(rule, scope, dataset);
  const metric = RULE_METRICS.find(metric => metric.id === rule.metric)!;
  const matchingPairs = preview && current ? selectScopedPairs({ ...scope, window: rule.window as typeof scope.window, weekIds: rule.window === scope.window ? scope.weekIds : undefined }, dataset).filter(pair => preview.pairIds.includes(pair.id)) : [];
  const disabled = !can('publish-rules');
  return <div className={styles.page}><WorkspaceCard title="Rule configuration" subtitle="Preview a typed, versioned rule against the applied population before publishing. Existing case evidence and decisions keep their original rule version.">
    <Toolbar><Button onClick={() => { setRule(newReviewRule(scope)); setPreview(null); setErrors([]); }}>Stockout rule</Button><Button onClick={() => { setRule({ ...newReviewRule(scope), id: 'sales-decline', name: 'Sales decline review', metric: 'salesChange', metricId: 'K01:growth', unit: '%', operator: 'lte', threshold: '-20', severity: 'High', rangedOnly: false, queue: 'Coverage/excess' }); setPreview(null); setErrors([]); }}>Sales decline rule</Button><Button onClick={() => { setRule(sourceMipRule(scope)); setPreview(null); setErrors([]); }}>S11 source recipe</Button></Toolbar>
    <div className={styles.formGrid}><DesignInput className={styles.field} label="Rule name" value={rule.name} onChange={event => patch({ name: event.target.value })}/><DesignInput className={styles.field} label="Stable rule ID" value={rule.id} onChange={event => patch({ id: event.target.value })}/><NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Metric" value={rule.metric} disabled={rule.sourceRecipe} onChange={event => patch({ metric: event.target.value as ReviewRule['metric'], metricId: RULE_METRICS.find(metric => metric.id === event.target.value)!.catalogueId, unit: event.target.value === 'sellableOh' ? scope.uom : RULE_METRICS.find(metric => metric.id === event.target.value)!.unit })}>{RULE_METRICS.map(metric => <option value={metric.id} key={metric.id}>{metric.label}</option>)}</NativeDesignSelect><NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Completed fiscal window" value={rule.window} onChange={event => patch({ window: event.target.value })}>{[...new Set([scope.window, 'R4', 'R13', 'R52', 'YTD'])].map(window => <option key={window}>{window}</option>)}</NativeDesignSelect><NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Operator" value={rule.operator} disabled={rule.sourceRecipe} onChange={event => patch({ operator: event.target.value as ReviewRule['operator'] })}>{[['lt', '<'], ['lte', '≤'], ['eq', '='], ['gte', '≥'], ['gt', '>'], ['between', 'Between inclusive'], ['missing', 'Is missing'], ['no-positive-base', 'No positive comparison base']].map(([id, label]) => <option value={id} key={id}>{label}</option>)}</NativeDesignSelect><DesignInput className={styles.field} label={`Threshold · ${metric.unit}`} type="number" step="any" disabled={['missing', 'no-positive-base'].includes(rule.operator) || rule.sourceRecipe} value={rule.threshold} onChange={event => patch({ threshold: event.target.value })}/>{rule.operator === 'between' && <DesignInput className={styles.field} label={`Upper threshold · ${metric.unit}`} type="number" step="any" value={rule.upper} onChange={event => patch({ upper: event.target.value })}/>}<div className={styles.field}>{rule.metric === 'sellableOh' ? <NativeDesignSelect orientation="top" width="100%" label="Threshold unit" value={rule.unit ?? scope.uom} onChange={event => patch({ unit: event.target.value })}>{[...new Set([scope.uom, ...dataset.products.map(item => item.uom)])].map(unit => <option key={unit}>{unit}</option>)}</NativeDesignSelect> : <DesignInput label="Threshold unit" readOnly value={metric.unit}/>}</div><DesignInput className={styles.field} label="Minimum qualifying pair-weeks" type="number" min="0" step="any" value={rule.minExposure} onChange={event => patch({ minExposure: event.target.value })}/><NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Severity" value={rule.severity} onChange={event => patch({ severity: event.target.value as ReviewRule['severity'] })}>{['Critical', 'High', 'Watch'].map(priority => <option key={priority}>{priority}</option>)}</NativeDesignSelect><NativeDesignSelect orientation="top" width="100%" className={styles.field} label="Queue" value={rule.queue} onChange={event => patch({ queue: event.target.value as ReviewRule['queue'] })}>{QUEUES.map(queue => <option key={queue}>{queue}</option>)}</NativeDesignSelect><DesignInput className={styles.field} label="Owner" value={rule.owner} onChange={event => patch({ owner: event.target.value })}/><DesignInput className={styles.field} label="Effective from" type="date" value={rule.effectiveFrom} onChange={event => patch({ effectiveFrom: event.target.value })}/><DesignInput className={styles.field} label="Effective to · optional" type="date" value={rule.effectiveTo} onChange={event => patch({ effectiveTo: event.target.value })}/></div>
    <div className={styles.checkRow}><DesignCheckbox label={<>Currently ranged pairs only</>} checked={rule.rangedOnly} onChange={event => patch({ rangedOnly: event.target.checked })}/><DesignCheckbox label={<>Retain positive sellable-stock exposure</>} checked={rule.stockOnly} onChange={event => patch({ stockOnly: event.target.checked })}/></div>
    <details className={styles.details}><summary>Exceptions · {rule.excludedItemIds.length} excluded SKUs</summary><div className={styles.checkList}>{dataset.products.map(item => <DesignCheckbox key={item.id} label={<>{item.id} · {item.name}</>} checked={rule.excludedItemIds.includes(item.id)} onChange={event => patch({ excludedItemIds: event.target.checked ? [...rule.excludedItemIds, item.id] : rule.excludedItemIds.filter(id => id !== item.id) })}/>)}</div></details>
    <p className={styles.helper}>{rule.metricId ?? metric.catalogueId} · {rule.definitionVersion ?? 'proposed base'}. {metric.definition} Scope is inherited from the header; exceptions narrow it. There is no global minimum-sales $500 gate: zero-sales stock exposure remains eligible for review.</p>
    {rule.sourceRecipe && <div className={styles.notice}>Source S11 uses <strong>MIP ≥ 6 AND not blank</strong>, despite “greater than 6” in the filename. Source level/status/type predicates require the original export contract; they are not invented here. Missing MIP or those fields means this source cohort cannot be claimed as reproduced.</div>}
    {errors.length > 0 && <div className={styles.errors} role="alert">{errors.map(error => <p key={error}>{error}</p>)}</div>}
    <div className={styles.actions}><Button onClick={() => { const next = previewReviewRule(rule, scope, dataset); setPreview(next); setErrors(next.errors); }}>Preview matching evidence</Button><Button variant="primary" disabled={disabled || !current || !!preview?.errors.length} onClick={() => { const result = publishReviewRule(versions, rule, preview, scope, dataset, role, can('publish-rules')); setErrors(result.errors); if (result.record) { setVersions(result.versions); addNotice(`${result.record.id} v${result.record.version} published locally. Prior case evidence is unchanged.`); } }}>Publish new version</Button>{disabled && <span className={styles.helper}>Administrator permission is required to publish. Preview does not save a rule.</span>}</div>
    {preview && !current && <div className={styles.notice}>Rule or scope changed. Preview again before publishing.</div>}
  </WorkspaceCard>
    {preview && current && <WorkspaceCard title="Rule preview" subtitle={`Evaluated ${preview.evaluatedAt} · ${preview.datasetVersion}. No cases or operational commitments are created by preview.`}><div className={styles.counts}><MetricCard label="Scanned pairs" value={preview.scannedPairs}/><MetricCard label="Matched pairs / SKUs" value={`${preview.pairIds.length} / ${preview.itemIds.length}`}/><MetricCard label="Existing open cases" value={preview.caseIds.length}/><MetricCard label="Matched OH cost" value={preview.ohCost === null ? 'Unavailable' : new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(preview.ohCost)}/></div><p className={styles.helper}>{preview.unknownCount} eligible pair values are unavailable. A missing-value rule is explicit; unavailable does not satisfy a numeric threshold.</p><WorkspaceTable rows={matchingPairs} rowKey={pair => pair.id} caption="Rule preview contributing pairs" columns={[{ key: 'pair', label: 'Pair', render: pair => <button className={styles.link} onClick={() => navigate({ view: 'pair', id: pair.itemId, storeId: pair.storeId })}>{pair.itemId} × {pair.storeId}</button> }, { key: 'state', label: 'Range / stock', value: pair => pair.matrixState }, { key: 'sales', label: 'Net sales', render: pair => <Metric metric={pair.sales}/> }, { key: 'stock', label: 'Sellable OH', render: pair => <Metric metric={pair.sellableOh} unit/> }, { key: 'cost', label: 'OH cost', render: pair => <Metric metric={pair.ohCost}/> }]}/></WorkspaceCard>}
    <WorkspaceCard title="Published versions" subtitle="Immutable local rule snapshots with their preview scope and evaluation date.">{!versions.length ? <DataState state="empty" description="No rule has been published in this review context."/> : <ol className={styles.history}>{[...versions].reverse().map(version => <li key={`${version.id}:${version.version}`}><strong>{version.rule.name} · v{version.version}</strong><p>{version.rule.metric} {version.rule.operator} {version.rule.threshold}{version.rule.operator === 'between' ? ` – ${version.rule.upper}` : ''} · {version.rule.window} · {version.rule.severity}</p><small>{version.publishedBy} · published {version.publishedAt} · evaluated {version.preview.evaluatedAt} · {version.preview.pairIds.length} matched pairs</small><details><summary>Inspect frozen rule and scope</summary><pre className={styles.pre}>{JSON.stringify(version, null, 2)}</pre></details><Button variant="ghost" onClick={() => { setRule(structuredClone(version.rule)); setPreview(null); setErrors([]); }}>Edit as next draft version</Button></li>)}</ol>}</WorkspaceCard>
  </div>;
}

export function LearningRegister() {
  const { learnings, scope, navigate, dataset, cases, drafts } = useWorkspace();
  const [settings,setSettings]=useViewState<LearningRegisterSettings>('learning-register-settings',{direction:'origin',destinationId:''});
  const destinations=acceptedLearningDestinations(learnings);
  const rows=learningRegisterRows(learnings,scope.reviewId,settings);
  const destinationOptions=[{value:'',label:'Choose a destination PLR'},...destinations.map(id=>({value:id,label:dataset.reviews?.find(review=>review.id===id)?.name??id}))];
  if(settings.destinationId&&!destinations.includes(settings.destinationId))destinationOptions.push({value:settings.destinationId,label:`${settings.destinationId} · no accepted learnings`});
  return <WorkspaceCard title="PLR learning register" subtitle="Review this PLR’s evidence or read accepted learnings carried forward to a named next PLR." actions={<Button onClick={() => navigate({ view: 'overview', subview: 'learning' })}>Review PLR and author learning</Button>}>
    <Toolbar ariaLabel="Learning register scope"><ButtonGroup aria-label="Learning register direction" options={[{value:'origin',label:'From this PLR'},{value:'destination',label:'For next PLR'}]} selectedOption={settings.direction} onChange={(_event,value)=>setSettings({...settings,direction:value==='destination'?'destination':'origin',destinationId:settings.destinationId||destinations[0]||''})}/>{settings.direction==='destination'&&<DesignSelect label="Destination PLR" aria-label="Learning destination PLR" value={settings.destinationId} options={destinationOptions} width={260} onChange={destinationId=>setSettings({...settings,destinationId})}/>}<Pill>{rows.length} {settings.direction==='destination'?'accepted carry-forward learnings':'source learnings'}</Pill></Toolbar>
    <p className={styles.helper}>{settings.direction==='destination'?`Destination reading view${settings.destinationId?` · ${settings.destinationId}`:''}. Only accepted learnings are included. This does not create a future PLR or change the applied review, sales window or approval.`:`Origin ${scope.reviewId}. Pending hypotheses and accepted conclusions retain their separate review states.`}</p>
    {!rows.length ? <DataState state="empty" title={settings.direction==='destination'?'No accepted learnings for this destination':'No learnings from this PLR'} description={settings.direction==='destination'?'Choose a destination with accepted records, or review and accept a source learning first. Pending conclusions are not carried forward.':'Investigate the original cohort, then record a question, evidence, conclusion and limitations in Overview.'}/> : rows.map(learning => {
      const origin=learningOriginScope(learning,scope,dataset),linkedCases=learningCaseLinks(learning,cases,drafts);
      return <article className={styles.learning} key={learning.id}><div className={styles.actions}><strong>{learning.question}</strong><Pill tone={learning.state === 'Accepted' ? 'success' : 'warning'}>{learning.state}</Pill></div><p><b>Hypothesis:</b> {learning.hypothesis || 'No hypothesis recorded.'}</p><p><b>Conclusion:</b> {learning.conclusion || 'Pending reviewed conclusion.'}</p><small>Origin {learning.reviewId} / {learning.version} → {learning.nextReviewId || 'Destination pending'}</small><dl className={styles.facts}><dt>Owner / confidence</dt><dd>{learning.owner} · {learning.confidence}</dd><dt>Reviewed by</dt><dd>{learning.reviewedBy || 'Pending review'}</dd><dt>Reviewed at</dt><dd>{learning.reviewedAt || 'Not yet reviewed'}</dd><dt>Evidence / exact scope</dt><dd>{learning.evidenceIds.length} references · {learning.pairIds.length} pairs</dd></dl><div className={styles.actions}><Button variant="ghost" disabled={!origin} title={origin?'Open the connected source approval and its recorded evidence':'The source approval is not connected in this local dataset.'} onClick={()=>{if(origin)navigate({view:'overview',subview:'learning'},{scope:origin,localSelection:learning.pairIds.length?{label:`Learning ${learning.id} · source evidence`,pairIds:[...learning.pairIds]}:null});}}>Open origin PLR</Button>{linkedCases.map(record=><Button key={record.id} variant="ghost" onClick={()=>navigate({view:'case',id:record.id},origin?{scope:origin,localSelection:null}:undefined)}>Open source case {record.id}</Button>)}</div><details><summary>Linked evidence and exact pairs</summary><p>{learning.evidenceIds.join(', ')||'No evidence references recorded.'}</p><p>{learning.pairIds.join(', ')||'Review-level learning; no narrower pair cohort recorded.'}</p></details></article>;
    })}
  </WorkspaceCard>;
}

